<!-- Leaflet Map Assets --> <link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css" crossorigin=""/> <script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js" crossorigin=""></script> <!-- Donor Dashboard Panel --> <!-- 1. OVERVIEW SECTION --> <div id="overview-panel" class="dashboard-view-panel"> <!-- Stats Cards Grid --> <div class="stats-grid"> <div class="glass-panel stat-card"> <div class="stat-info"> <h3>My Physical Listings</h3> <div class="stat-number" id="statMyListings">0</div> </div> </div> <div class="glass-panel stat-card"> <div class="stat-info"> <h3>Active Matches</h3> <div class="stat-number" id="statMyMatches">0</div> </div> </div> <div class="glass-panel stat-card"> <div class="stat-info"> <h3>Completed Support</h3> <div class="stat-number" id="statCompletedDons">0</div> </div> </div> </div> <!-- Quick action layout --> <div class="dashboard-grid"> <!-- Post Available Physical Item Listing --> <div class="glass-panel" style="padding: 30px; background: #FFFFFF;"> <div class="card-header"> <h3 class="card-title">Offer Surplus Material / Items</h3> <span style="font-size: 0.8rem; color: var(--color-primary); font-weight: 700;">PHYSICAL DONATION</span> </div> <form id="formPostDonation"> <input type="hidden" id="donItemId" value=""> <div class="grid-cols-2"> <div class="form-group"> <label class="form-label">Material / Item Name</label> <input type="text" class="form-control" id="donItemName" placeholder="e.g. First Aid Kits / Rice Rations" required> </div> <div class="form-group"> <label class="form-label">Category</label> <select class="form-control form-select" id="donCategory" required> <option value="Education Supplies"> Education Supplies</option> <option value="Medical Supplies"> Medical Supplies</option> <option value="Food & Nutrition"> Food & Nutrition</option> <option value="Furniture"> Furniture</option> <option value="Electronics & IT Equipment"> Electronics & IT Equipment</option> <option value="Clothing & Personal Care"> Clothing & Personal Care</option> <option value="Household Essentials"> Household Essentials</option> <option value="Other Supplies"> Other Supplies</option> </select> </div> </div> <div class="grid-cols-2"> <div class="form-group"> <label class="form-label">Quantity</label> <input type="number" class="form-control" id="donQuantity" min="1" value="1" required> </div> <div class="form-group"> <label class="form-label">Condition</label> <select class="form-control form-select" id="donCondition" required> <option value="New">Brand New</option> <option value="Used">Gently Used</option> <option value="Refurbished">Refurbished</option> </select> </div> </div> <div class="form-group"> <label class="form-label">Item Photo (PNG/JPG)</label> <div style="display: flex; gap: 12px; align-items: center;"> <input type="file" id="itemPhotoUploadInput" class="form-control" style="padding: 8px 12px; flex-grow: 1;" accept=".png,.jpg,.jpeg"> <input type="hidden" id="donPhotoUrl" value=""> </div> <div id="itemPhotoPreview" style="margin-top: 10px; display: none;"> <img id="imgPreviewSource" src="" style="max-width: 100px; border-radius: var(--radius-sm); border: 1px solid var(--color-border);" alt="Preview"> </div> </div> <div class="grid-cols-2">
    <div class="form-group">
        <label class="form-label">Availability Date</label>
        <input type="date" class="form-control" id="donAvailability">
    </div>
    <div class="form-group">
        <label class="form-label">Delivery Method</label>
        <select class="form-control form-select" id="donDeliveryMethod">
            <option value="donor_delivery">Donor Will Deliver to Receiver</option>
            <option value="receiver_pickup">Receiver Pickup Required</option>
            <option value="courier">Courier / Logistics</option>
        </select>
    </div>
</div> <div class="form-group"> <label class="form-label">Description / Special Handover Notes</label> <textarea class="form-control" id="donDescription" rows="2" placeholder="Enter expiration date, weight, dimensions, or pickup instructions..."></textarea> </div> <button class="btn btn-primary" type="submit" id="formSubmitBtn" style="width: 100%;"> Post Physical Donation Listing </button> </form> </div> <!-- Announcements Panel --> <div class="glass-panel" style="padding: 30px; background: #FFFFFF;"> <div class="card-header"> <h3 class="card-title">Announcements</h3> </div> <div id="announcementsContainer" style="max-height: 420px; overflow-y: auto;"> <!-- Filled dynamically by app.js --> </div> </div> </div> </div> <!-- 2. MY LISTINGS SECTION --> <div id="listings-panel" class="dashboard-view-panel" style="display: none;"> <div class="glass-panel" style="padding: 30px; margin-bottom: 24px; background: #FFFFFF;"> <div class="card-header"> <h3 class="card-title">Manage Offered Material Listings</h3> </div> <div style="overflow-x: auto;"> <table class="data-table"> <thead> <tr> <th>Photo</th> <th>Material Item</th> <th>Category</th> <th>Quantity</th> <th>Status</th> <th>Actions</th> </tr> </thead> <tbody id="donorListingsBody"> <!-- Filled dynamically by app.js --> </tbody> </table> </div> </div> </div> <!-- 3. REQUESTS CATALOGUE SECTION (BROWSE RECEIVER REQUESTS) --> <div id="needs-catalogue-panel" class="dashboard-view-panel" style="display: none;"> <div class="glass-panel" style="padding: 30px; margin-bottom: 24px; background: #FFFFFF;"> <div class="card-header"> <h3 class="card-title">Browse Verified Receiver Requests</h3> <span style="font-size: 0.8rem; color: var(--color-primary); font-weight: 700;">APPROVED REQUESTS</span> </div> <!-- Multi-Filter Control Toolbar --> <div class="glass-panel" style="padding: 16px; margin-bottom: 24px; background: #FBF5DD;"> <div class="grid-cols-3" style="gap: 16px; margin-bottom: 12px;"> <div> <label class="form-label" style="font-size: 0.75rem;">Keyword Search</label> <input type="text" id="searchDonorNeeds" class="form-control" placeholder="Search requests..."> </div> <div> <label class="form-label" style="font-size: 0.75rem;">Request Type</label> <select id="filterReqType" class="form-control form-select"> <option value="all">All Request Types</option> <option value="physical">Physical Items</option> <option value="monetary">Monetary Support</option> <option value="volunteer">Volunteer Activities</option> </select> </div> <div> <label class="form-label" style="font-size: 0.75rem;">Category</label> <select id="filterReqCategory" class="form-control form-select"> <option value="all">All Categories</option> <option value="Education Supplies"> Education Supplies</option> <option value="Medical Supplies"> Medical Supplies</option> <option value="Food & Nutrition"> Food & Nutrition</option> <option value="Furniture"> Furniture</option> <option value="Electronics & IT Equipment"> Electronics & IT Equipment</option> <option value="Clothing & Personal Care"> Clothing & Personal Care</option> <option value="Household Essentials"> Household Essentials</option> <option value="Other Supplies"> Other Supplies</option> </select> </div> </div> <div class="grid-cols-3" style="gap: 16px;"> <div> <label class="form-label" style="font-size: 0.75rem;">District / Location</label> <select id="filterReqDistrict" class="form-control form-select"> <option value="all">All Districts (25)</option> <option value="Ampara">Ampara</option> <option value="Anuradhapura">Anuradhapura</option> <option value="Badulla">Badulla</option> <option value="Batticaloa">Batticaloa</option> <option value="Colombo">Colombo</option> <option value="Galle">Galle</option> <option value="Gampaha">Gampaha</option> <option value="Hambantota">Hambantota</option> <option value="Jaffna">Jaffna</option> <option value="Kalutara">Kalutara</option> <option value="Kandy">Kandy</option> <option value="Kegalle">Kegalle</option> <option value="Kilinochchi">Kilinochchi</option> <option value="Kurunegala">Kurunegala</option> <option value="Mannar">Mannar</option> <option value="Matale">Matale</option> <option value="Matara">Matara</option> <option value="Moneragala">Moneragala</option> <option value="Mullaitivu">Mullaitivu</option> <option value="Nuwara Eliya">Nuwara Eliya</option> <option value="Polonnaruwa">Polonnaruwa</option> <option value="Puttalam">Puttalam</option> <option value="Ratnapura">Ratnapura</option> <option value="Trincomalee">Trincomalee</option> <option value="Vavuniya">Vavuniya</option> </select> </div> <div> <label class="form-label" style="font-size: 0.75rem;">Urgency Level</label> <select id="filterReqUrgency" class="form-control form-select"> <option value="all">All Priority Levels</option> <option value="High">Emergency / High Priority</option> <option value="Medium">Medium Priority</option> <option value="Low">Low Priority</option> </select> </div> <div style="display: flex; align-items: flex-end;"> <button class="btn btn-secondary" id="btnResetFilters" style="width: 100%; padding: 10px;"> Reset Filters </button> </div> </div> </div> <!-- Requests Grid --> <div class="grid-cols-3" id="donorNeedsGrid" style="gap: 20px;"> <!-- Filled dynamically by app.js --> </div> </div> </div> <!-- 4. MATCHES & CONNECTIONS SECTION --> <div id="matching-panel" class="dashboard-view-panel" style="display: none;"> <div class="dashboard-grid"> <div class="glass-panel" style="padding: 30px; background: #FFFFFF;"> <div class="card-header"> <h3 class="card-title">Matches & Connections Recommendations</h3> <span class="badge badge-success">Algorithm Active</span> </div> <div id="donorMatchesContainer" style="max-height: 500px; overflow-y: auto;"> <!-- Filled dynamically by app.js --> </div> </div> <div class="glass-panel" style="padding: 30px; background: #FFFFFF;"> <div class="card-header"> <h3 class="card-title">Real-Time Distance Map</h3> </div> <div class="map-container" id="liveSimulatedMap"></div> <small style="color: var(--color-text-muted); display: block; margin-top: 12px; text-align: center;"> Calculates geometric distance (in km) between your location and active matched needs. </small> </div> </div> </div> <!-- 5. CHAT/MESSAGES SECTION --> <div id="chat-panel" class="dashboard-view-panel" style="display: none;"> <div class="dashboard-grid" style="grid-template-columns: 1.1fr 1.4fr; gap: 20px;"> <div style="display: flex; flex-direction: column; gap: 20px;"> <div class="glass-panel" style="padding: 24px; background: #FFFFFF;"> <div class="card-header" style="margin-bottom: 16px; padding-bottom: 10px;"> <h3 class="card-title">Your Conversations</h3> </div> <div id="chatMatchesList" style="max-height: 250px; overflow-y: auto; display: flex; flex-direction: column; gap: 10px;"> <!-- Filled dynamically by app.js --> </div> </div> <div class="glass-panel" style="padding: 24px; background: #FFFFFF;"> <div class="card-header" style="margin-bottom: 16px; padding-bottom: 10px;"> <h3 class="card-title">Support Progress Milestones</h3> </div> <div id="trackingStatusTimeline"> <div style="text-align: center; color: var(--color-text-muted); padding: 20px; font-size: 0.9rem;">Select a conversation to inspect donation tracking milestones.</div> </div> </div> </div> <div class="glass-panel chat-widget"> <div class="chat-header"> <div class="profile-avatar" style="width: 32px; height: 32px;"></div> <div> <h4 style="font-size: 0.95rem;" id="chatPeerName">Select Recipient</h4> <small style="color: var(--color-secondary); font-size: 0.75rem;">Verified Connection</small> </div> </div> <div class="chat-messages" id="chatMessagesContainer"> <!-- Filled dynamically by app.js --> </div> <div class="chat-input-panel"> <input type="text" class="form-control" id="chatMessageInput" placeholder="Type a message to coordinate handover details..." style="flex-grow: 1;"> <button class="btn btn-primary" id="btnSendChatMessage">Send</button> </div> </div> </div> </div> <!-- 6. NOTIFICATIONS SECTION --> <div id="notifications-panel" class="dashboard-view-panel" style="display: none;"> <div class="glass-panel" style="padding: 30px; background: #FFFFFF;"> <div class="card-header"> <h3 class="card-title">My Alerts Log</h3> </div> <div id="notificationsListContainer" style="max-height: 500px; overflow-y: auto;"> <!-- Filled dynamically by app.js --> </div> </div> </div> <!-- MODAL DIALOG: MONETARY DONATION OFFER --> <div class="custom-modal-backdrop" id="modalMonetaryDonation"> <div class="custom-modal-card"> <h3 style="color: var(--color-primary); margin-bottom: 12px;" id="mdlMonTitle">Monetary Transfer Details</h3> <p style="font-size: 0.9rem; color: var(--color-text-muted); margin-bottom: 16px;"> Transfer directly to the receiver's official verified bank account, then upload your transaction receipt. </p> <div class="glass-panel" style="padding: 16px; background: #FBF5DD; margin-bottom: 20px; font-size: 0.85rem; border: 1px solid var(--color-border-dark);"> <div style="font-weight: 700; color: var(--color-primary); margin-bottom: 6px;">Verified Receiver Bank Details:</div> <div id="mdlBankDetailsContent">Loading bank info...</div> </div> <form id="formSubmitMonetaryDonation"> <input type="hidden" id="mdlMonRequestId" value=""> <div class="grid-cols-2"> <div class="form-group"> <label class="form-label">Transfer Amount (LKR)</label> <input type="number" class="form-control" id="mdlMonAmount" required min="100"> </div> <div class="form-group"> <label class="form-label">Transfer Date</label> <input type="date" class="form-control" id="mdlMonDate" required> </div> </div> <div class="form-group"> <label class="form-label">Transaction Reference Number</label> <input type="text" class="form-control" id="mdlMonRef" placeholder="e.g. TXN-98765432" required> </div> <div class="form-group"> <label class="form-label">Transaction Receipt (PNG/JPG/PDF)</label> <input type="file" id="monReceiptUploadInput" class="form-control" accept=".pdf,.png,.jpg,.jpeg" required> <input type="hidden" id="mdlMonReceiptUrl" value=""> </div> <div style="display: flex; gap: 12px; justify-content: flex-end; margin-top: 24px;"> <button type="button" class="btn btn-secondary" onclick="closeCustomModal('modalMonetaryDonation')">Cancel</button> <button type="submit" class="btn btn-primary">Confirm Monetary Offer</button> </div> </form> </div> </div> <!-- MODAL DIALOG: VOLUNTEER OFFER --> <div class="custom-modal-backdrop" id="modalVolunteerOffer"> <div class="custom-modal-card"> <h3 style="color: var(--color-primary); margin-bottom: 12px;" id="mdlVolTitle">Volunteer Support Offer</h3> <p style="font-size: 0.9rem; color: var(--color-text-muted); margin-bottom: 16px;"> Specify your availability, skills, and any equipment you can bring to assist the receiver organisation. </p> <form id="formSubmitVolunteerOffer"> <input type="hidden" id="mdlVolRequestId" value=""> <div class="grid-cols-2"> <div class="form-group"> <label class="form-label">Number of Volunteers Attending</label> <input type="number" class="form-control" id="mdlVolCount" min="1" value="1" required> </div> <div class="form-group"> <label class="form-label">Your Availability / Shift</label> <input type="text" class="form-control" id="mdlVolAvailability" placeholder="e.g. Full Day / Morning Shift" required> </div> </div> <div class="form-group"> <label class="form-label">Relevant Skills / Experience</label> <input type="text" class="form-control" id="mdlVolSkills" placeholder="e.g. First Aid, Carpentry, Painting"> </div> <div class="glass-panel" style="padding: 16px; background: #FBF5DD; border: 1px solid var(--color-border-dark); margin-bottom: 20px;"> <h4 style="font-size: 0.85rem; color: var(--color-primary); margin-bottom: 6px;">Equipment Support (Optional)</h4> <div style="font-size: 0.8rem; color: var(--color-text-muted); margin-bottom: 10px;" id="mdlVolEquipmentRequiredNotice"> Specify any required equipment you can bring and available quantities. </div> <div class="form-group" style="margin-bottom: 0;"> <label class="form-label" style="font-size: 0.75rem;">Equipment Provided & Quantities</label> <input type="text" class="form-control" id="mdlVolEquipmentProvided" placeholder="e.g. 2 Ekel Brooms, 1 Garden Cutter"> </div> </div> <div style="display: flex; gap: 12px; justify-content: flex-end; margin-top: 24px;"> <button type="button" class="btn btn-secondary" onclick="closeCustomModal('modalVolunteerOffer')">Cancel</button> <button type="submit" class="btn btn-primary">Submit Volunteer Offer</button> </div> </form> </div> </div> <script> function closeCustomModal(id) {
        const modal = document.getElementById(id);
        if (modal) modal.classList.remove("active");
    }

    document.addEventListener("DOMContentLoaded", () => {
        const itemPhotoInput = document.getElementById("itemPhotoUploadInput");
        const itemPhotoUrl = document.getElementById("donPhotoUrl");
        const previewDiv = document.getElementById("itemPhotoPreview");
        const previewImg = document.getElementById("imgPreviewSource");
        
        if (itemPhotoInput) {
            itemPhotoInput.addEventListener("change", async (e) => {
                const file = e.target.files[0];
                if (!file) return;
                
                const formData = new FormData();
                formData.append("file", file);
                if (window.showToast) window.showToast("Uploading item photo...", "info");
                
                try {
                    const response = await fetch("api/upload_handler.php", {
                        method: "POST",
                        body: formData
                    });
                    const result = await response.json();
                    
                    if (result.success) {
                        itemPhotoUrl.value = result.filePath;
                        previewImg.src = result.filePath;
                        previewDiv.style.display = "block";
                        if (window.showToast) window.showToast("Photo uploaded successfully", "success");
                    } else {
                        if (window.showToast) window.showToast(result.error || "Upload failed.", "danger");
                        itemPhotoInput.value = "";
                        previewDiv.style.display = "none";
                    }
                } catch (error) {
                    if (window.showToast) window.showToast("Upload server error.", "danger");
                    console.error(error);
                }
            });
        }

        const monReceiptInput = document.getElementById("monReceiptUploadInput");
        const monReceiptUrl = document.getElementById("mdlMonReceiptUrl");
        if (monReceiptInput) {
            monReceiptInput.addEventListener("change", async (e) => {
                const file = e.target.files[0];
                if (!file) return;
                const formData = new FormData();
                formData.append("file", file);
                if (window.showToast) window.showToast("Uploading transaction receipt...", "info");
                try {
                    const response = await fetch("api/upload_handler.php", {
                        method: "POST",
                        body: formData
                    });
                    const result = await response.json();
                    if (result.success) {
                        monReceiptUrl.value = result.filePath;
                        if (window.showToast) window.showToast("Receipt uploaded successfully", "success");
                    } else {
                        if (window.showToast) window.showToast(result.error || "Upload failed.", "danger");
                        monReceiptInput.value = "";
                    }
                } catch (err) {
                    if (window.showToast) window.showToast("Upload error.", "danger");
                    console.error(err);
                }
            });
        }
    }); </script> 